def test_solutions():
    solutions = []
    for a in range(1, 11):
        limit_b = 1006 // (a**2) + 100 
        if a == 1: limit_b = 1100
        for b in range(a, limit_b + 1):
            K1 = 2012 * b / (a**2)
            K2 = b**3 - 4024 / (a**3)
            c_approx = int(K1**0.5)
            for c in range(max(b, c_approx - 100), c_approx + 100):
                if a**3 * (b**3 + c**3) == 2012 * (a*b*c + 2):
                    solutions.append((a, b, c))
    return solutions

