def find_all_solutions():
    solutions = []
    for a in range(1, 11):
        # Calculate max_c for this a
        max_c = 0
        for c in range(1, 3000):
            if a**2 * c**3 <= 2012 * c**2 + 4024 / a:
                max_c = c
            else:
                break

        for b in range(a, max_c + 1):
            # a^3*c^3 - (2012*a*b)*c + (a^3*b^3 - 4024) = 0
            # Let f(c) = a^3*c^3 - (2012*a*b)*c + (a^3*b^3 - 4024)
            # We can solve this cubic for c.
            # Or just iterate c from b to max_c.
            # However, c is also bounded by c^2 < 2012b/a.
            limit_c = int((2012 * b / a)**0.5)
            for c in range(b, min(max_c, limit_c) + 1):
                if a**3 * (b**3 + c**3) == 2012 * (a * b * c + 2):
                    solutions.append((a, b, c))
    return sorted(list(set(solutions)))

print(find_all_solutions())

